templates.template:
${result} <- tryCatch({
  ${cursor}
}, warning = function(w) {
  message("Warning: ", conditionMessage(w))
  NULL
}, error = function(e) {
  message("Error: ", conditionMessage(e))
  NULL
}, finally = {
  
})

${pb} <- txtProgressBar(min = 0, max = ${n}, style = 3)
for (${i} in seq_len(${n})) {
  ${cursor}
  setTxtProgressBar(${pb}, ${i})
}
close(${pb})

new_${plant} <- function(name, height = 0) {
  obj <- list(name = name, height = height)
  class(obj) <- "${plant}"
  obj
}

print.${plant} <- function(x, ...) {
  cat("${plant}:", x$$name, "- height:", x$$height, "\n")
  invisible(x)
}

p <- new_${plant}("Corynephorus canescens", 15)
print(p)

setClass("${Plant}",
  slots = c(name = "character", height = "numeric"),
  prototype = list(name = NA_character_, height = 0),
  validity = function(object) {
    if (length(object@height) != 1 || object@height < 0) {
      return("height must be a single non-negative number")
    }
    TRUE
  }
)

setGeneric("grow", function(object, amount) standardGeneric("grow"))
setMethod("grow", "${Plant}", function(object, amount) {
  object@height <- object@height + amount
  validObject(object)
  object
})

p <- new("${Plant}", name = "Corynephorus canescens", height = 15)
p <- grow(p, 2)
p@height

${Plant} <- setRefClass("${Plant}",
  fields = list(name = "character", weight = "numeric", age = "numeric"),
  methods = list(
    getName = function() {
      name
    },
    setWeight = function(value) {
      weight <<- value
      invisible(.self)
    },
    show = function() {
      cat("${Plant}:", name, "- weight:", weight, "- age:", age, "\n")
    }
  )
)
p <- ${Plant}$$new(name = "Corynephorus canescens", weight = 15, age = 3.5)
p$$setWeight(16)
p

library(R6)
${Plant} <- R6Class("${Plant}",
  public = list(
    name = NULL,
    height = NULL,
    initialize = function(name, height = 0) {
      self$$name <- name
      self$$height <- height
    },
    grow = function(amount) {
      self$$height <- self$$height + amount
      invisible(self)
    },
    print = function(...) {
      cat("${Plant}:", self$$name, "- height:", self$$height, "\n")
      invisible(self)
    }
  )
)
p <- ${Plant}$$new("Corynephorus canescens", 15)
p$$grow(2)
p
